/**
 * The browser QAOA must not drift from the published Python QAOA.
 *
 * `web/tests/fixtures/qaoa_golden.json` is generated by
 * `scripts/export_qaoa_fixture.py` from the same real Potts coefficients the
 * Python benchmark uses. This file requires the TypeScript implementation in
 * `src/science/qaoa.ts` to reproduce it to 1e-9 - the objective tensor, the
 * statevector for fixed angles, and every quantity derived from both.
 *
 * Angles in the fixture are fixed, not optimised. Two Nelder-Mead runs in two
 * languages legitimately take different floating-point paths, so the optimiser
 * is tested separately (determinism, and improvement over the random baseline);
 * what must agree exactly is the physics.
 */

import { describe, expect, it } from 'vitest';

import golden from '../fixtures/qaoa_golden.json';
import { realModel } from '../helpers/model';
import {
  buildXyProblem,
  circuitCost,
  interpolateAngles,
  optimiseXyQaoa,
  probabilitiesOf,
  rampStart,
  scaledPhase,
  slotClassesOf,
  codesFor,
  sweepXyDepths,
  xyQaoaState,
  applyXyMixer,
  uniformFeasibleState,
  expectationOf,
} from '../../src/science/qaoa';

const TOLERANCE = golden.tolerance ?? 1e-9;
const model = realModel();

describe('QAOA fixture integrity', () => {
  it('declares the schema and the honesty warning', () => {
    expect(golden.schema).toBe('qbind-select/qaoa-golden/1');
    expect(golden.warning).toMatch(/NO QUANTUM HARDWARE/i);
    expect(golden.cases.length).toBeGreaterThanOrEqual(2);
  });
});

describe.each(golden.cases)('parity: $name', (testCase) => {
  const problem = buildXyProblem(model.flat, {
    lambda: testCase.lambda,
    fixedCodes: testCase.fixedCodes,
    freePositions: testCase.freePositions,
  });

  it('agrees on the shape of the feasible subspace', () => {
    expect(problem.slots).toBe(testCase.slots);
    expect(problem.dimension).toBe(testCase.dimension);
    expect(problem.nominalQubits).toBe(testCase.nominalQubits);
  });

  it('agrees on the reduction constant and effective one-body terms', () => {
    expect(problem.contextConstant).toBeCloseTo(testCase.contextConstant, 9);
    expect(problem.effectiveLinear.length).toBe(testCase.effectiveLinear.length);
    testCase.effectiveLinear.forEach((expected: number, index: number) => {
      expect(Math.abs(problem.effectiveLinear[index] - expected)).toBeLessThan(TOLERANCE);
    });
  });

  it('agrees on the objective tensor, including its axis order', () => {
    const { objective } = testCase;
    expect(Math.abs(problem.bestEnergy - objective.best)).toBeLessThan(TOLERANCE);
    expect(Math.abs(problem.worstEnergy - objective.worst)).toBeLessThan(TOLERANCE);
    expect(Math.abs(problem.meanEnergy - objective.mean)).toBeLessThan(TOLERANCE);
    expect(problem.bestIndex).toBe(objective.bestIndex);
    expect(slotClassesOf(problem, problem.bestIndex)).toEqual(objective.bestSlotClasses);

    // Spot energies at fixed indices: catches a transposed axis order that
    // matching aggregate statistics would hide.
    objective.sampleIndices.forEach((index: number, position: number) => {
      const expected = objective.sampleEnergies[position];
      expect(Math.abs(problem.objective[index] - expected)).toBeLessThan(TOLERANCE);
    });

    let checksum = 0;
    for (let i = 0; i < problem.dimension; i += 1) {
      checksum += problem.objective[i] * problem.objective[i];
    }
    // Relative comparison: the checksum is a sum of ~1e5 squared energies, so
    // an absolute 1e-9 bound would be below float64 resolution here.
    expect(Math.abs(checksum - objective.checksum) / Math.abs(objective.checksum)).toBeLessThan(
      1e-12,
    );
  });

  it('agrees on the gate cost a device would pay', () => {
    const slotPairs = (testCase.slots * (testCase.slots - 1)) / 2;
    const cost = circuitCost(testCase.slots, 2, { coupledPairs: slotPairs * 36 });
    expect(cost.qubits).toBe(testCase.circuitCost.qubits);
    expect(cost.statePrepCnot).toBe(testCase.circuitCost.w_state_prep_cnot);
    expect(cost.phaseSeparatorCnot).toBe(testCase.circuitCost.phase_separator_cnot);
    expect(cost.mixerCnot).toBe(testCase.circuitCost.mixer_cnot);
    expect(cost.cnotTotalLowerBound).toBe(testCase.circuitCost.cnot_total_lower_bound);
  });

  describe.each(testCase.runs)('statevector at p=$gammas.length', (run) => {
    const phase = scaledPhase(problem);
    const state = xyQaoaState(problem, phase, run.gammas, run.betas);
    const probabilities = probabilitiesOf(state);

    it('keeps the state normalised', () => {
      let norm = 0;
      for (let i = 0; i < state.re.length; i += 1) {
        norm += state.re[i] * state.re[i] + state.im[i] * state.im[i];
      }
      expect(Math.abs(Math.sqrt(norm) - run.norm)).toBeLessThan(1e-11);
    });

    it('agrees on the expectation value', () => {
      const expectation = expectationOf(probabilities, problem.objective);
      expect(Math.abs(expectation - run.expectation)).toBeLessThan(TOLERANCE);
    });

    it('agrees on the most likely outcomes and their probabilities', () => {
      const order = Array.from({ length: probabilities.length }, (_, i) => i).sort((a, b) => {
        const difference = probabilities[b] - probabilities[a];
        return difference !== 0 ? difference : a - b;
      });
      run.topIndices.forEach((expectedIndex: number, position: number) => {
        const expectedProbability = run.topProbabilities[position];
        // Compare by probability rather than by index: exact ties are possible
        // and the two languages may order them differently.
        expect(Math.abs(probabilities[order[position]] - expectedProbability)).toBeLessThan(
          TOLERANCE,
        );
        expect(Math.abs(probabilities[expectedIndex] - expectedProbability)).toBeLessThan(
          TOLERANCE,
        );
      });
    });

    it('agrees on the optimum probability and the distribution checksum', () => {
      expect(Math.abs(probabilities[problem.bestIndex] - run.optimumProbability)).toBeLessThan(
        TOLERANCE,
      );
      let squared = 0;
      for (let i = 0; i < probabilities.length; i += 1) squared += probabilities[i] ** 2;
      expect(Math.abs(squared - run.probabilitySquaredSum)).toBeLessThan(TOLERANCE);
    });
  });
});

describe('XY mixer properties', () => {
  const problem = buildXyProblem(model.flat, {
    lambda: 1,
    fixedCodes: [2, 3, 0, 0, 2, 2, 1, 2],
    freePositions: [0, 2, 7],
  });

  it('is unitary for arbitrary beta', () => {
    for (const beta of [0, 0.21, 1.4, -2.3, Math.PI]) {
      const state = uniformFeasibleState(problem.dimension);
      // Perturb away from the uniform state so the test is not trivially
      // satisfied by an eigenvector.
      for (let i = 0; i < state.re.length; i += 1) {
        state.re[i] += Math.sin(i * 0.7) * 0.001;
        state.im[i] = Math.cos(i * 1.3) * 0.001;
      }
      let before = 0;
      for (let i = 0; i < state.re.length; i += 1) {
        before += state.re[i] ** 2 + state.im[i] ** 2;
      }
      applyXyMixer(state, beta, problem.slots);
      let after = 0;
      for (let i = 0; i < state.re.length; i += 1) {
        after += state.re[i] ** 2 + state.im[i] ** 2;
      }
      expect(Math.abs(after - before)).toBeLessThan(1e-10);
    }
  });

  it('is the identity at beta = 0', () => {
    const state = uniformFeasibleState(problem.dimension);
    for (let i = 0; i < state.re.length; i += 1) state.re[i] = Math.sin(i);
    const before = Float64Array.from(state.re);
    applyXyMixer(state, 0, problem.slots);
    for (let i = 0; i < before.length; i += 1) {
      expect(Math.abs(state.re[i] - before[i])).toBeLessThan(1e-14);
    }
  });

  it('only rephases the uniform feasible state, which is an eigenvector', () => {
    const state = uniformFeasibleState(problem.dimension);
    applyXyMixer(state, 0.37, problem.slots);
    const firstRe = state.re[0];
    const firstIm = state.im[0];
    for (let i = 1; i < state.re.length; i += 1) {
      expect(Math.abs(state.re[i] - firstRe)).toBeLessThan(1e-12);
      expect(Math.abs(state.im[i] - firstIm)).toBeLessThan(1e-12);
    }
  });

  it('gives the uniform mean at depth zero', () => {
    const state = xyQaoaState(problem, scaledPhase(problem), [], []);
    const expectation = expectationOf(probabilitiesOf(state), problem.objective);
    expect(Math.abs(expectation - problem.meanEnergy)).toBeLessThan(1e-9);
  });
});

describe('optimiser behaviour', () => {
  const problem = buildXyProblem(model.flat, {
    lambda: 1,
    fixedCodes: [2, 3, 0, 0, 2, 2, 1, 2],
    freePositions: [0, 2, 7],
  });

  it('beats the uniform-random baseline and is always feasible', () => {
    const result = optimiseXyQaoa(problem, { depth: 2, restarts: 2, maxIterations: 120 });
    expect(result.validityRate).toBe(1);
    expect(result.approximationRatio).toBeGreaterThan(result.randomBaselineRatio);
    expect(result.topDesigns.length).toBeGreaterThan(0);
    for (const design of result.topDesigns) {
      expect(design.codes).toHaveLength(8);
      expect(design.codes.every((c) => c >= 0 && c < 6)).toBe(true);
    }
  });

  it('concentrates probability on the proven optimum', () => {
    const result = optimiseXyQaoa(problem, { depth: 3, restarts: 2, maxIterations: 150 });
    expect(result.enrichmentOverUniform).toBeGreaterThan(2);
    expect(result.optimumRank).toBeLessThanOrEqual(5);
    expect(Math.abs(result.provenOptimumEnergy - problem.bestEnergy)).toBeLessThan(TOLERANCE);
  });

  it('is deterministic for the same inputs', () => {
    const options = { depth: 2, restarts: 2, maxIterations: 80, seed: 7 } as const;
    const first = optimiseXyQaoa(problem, options);
    const second = optimiseXyQaoa(problem, options);
    expect(first.gammas).toEqual(second.gammas);
    expect(first.betas).toEqual(second.betas);
    expect(first.expectation).toBe(second.expectation);
  });

  it('reports real progress fractions', () => {
    const seen: number[] = [];
    optimiseXyQaoa(problem, {
      depth: 1,
      restarts: 2,
      maxIterations: 40,
      onProgress: (fraction) => seen.push(fraction),
    });
    expect(seen.length).toBeGreaterThan(0);
    expect(seen[seen.length - 1]).toBeCloseTo(1, 10);
    for (const fraction of seen) {
      expect(fraction).toBeGreaterThan(0);
      expect(fraction).toBeLessThanOrEqual(1);
    }
  });

  it('does not regress as depth increases', () => {
    const results = sweepXyDepths(problem, [1, 2, 3], { restarts: 1, maxIterations: 120 });
    expect(results.map((r) => r.depth)).toEqual([1, 2, 3]);
    for (let i = 1; i < results.length; i += 1) {
      expect(results[i].approximationRatio).toBeGreaterThanOrEqual(
        results[i - 1].approximationRatio - 1e-6,
      );
    }
  });

  it('rejects an invalid depth', () => {
    expect(() => optimiseXyQaoa(problem, { depth: 0 })).toThrow(/depth/i);
  });
});

describe('angle helpers', () => {
  it('builds a linear ramp', () => {
    const start = rampStart(2);
    expect(Array.from(start)).toHaveLength(4);
    expect(start[0]).toBeCloseTo(0.35, 12);
    expect(start[1]).toBeCloseTo(0.7, 12);
    expect(start[2]).toBeCloseTo(0.7, 12);
    expect(start[3]).toBeCloseTo(0.35, 12);
  });

  it('lifts a schedule to the next depth, keeping the endpoints', () => {
    const lifted = interpolateAngles(Float64Array.from([0.2, 0.6, 0.9, 0.5]), 3);
    expect(lifted).toHaveLength(6);
    expect(lifted[0]).toBeCloseTo(0.2, 12);
    expect(lifted[2]).toBeCloseTo(0.6, 12);
    expect(lifted[3]).toBeCloseTo(0.9, 12);
    expect(lifted[5]).toBeCloseTo(0.5, 12);
  });
});

describe('input validation', () => {
  it('rejects malformed problems', () => {
    const fixedCodes = [2, 3, 0, 0, 2, 2, 1, 2];
    expect(() =>
      buildXyProblem(model.flat, { lambda: 1, fixedCodes, freePositions: [] }),
    ).toThrow(/at least one/i);
    expect(() =>
      buildXyProblem(model.flat, { lambda: 1, fixedCodes, freePositions: [0, 0] }),
    ).toThrow(/distinct/i);
    expect(() =>
      buildXyProblem(model.flat, { lambda: 1, fixedCodes, freePositions: [0, 9] }),
    ).toThrow(/0\.\.7/);
    expect(() =>
      buildXyProblem(model.flat, { lambda: 1, fixedCodes: [0, 1], freePositions: [0] }),
    ).toThrow(/8 entries/);
    expect(() =>
      buildXyProblem(model.flat, {
        lambda: 1,
        fixedCodes: [0, 1, 2, 3, 4, 5, 6, 0],
        freePositions: [0],
      }),
    ).toThrow(/integers in 0\.\.5/);
  });

  it('rejects mismatched angle arrays', () => {
    const problem = buildXyProblem(model.flat, {
      lambda: 1,
      fixedCodes: [2, 3, 0, 0, 2, 2, 1, 2],
      freePositions: [0, 2],
    });
    expect(() => xyQaoaState(problem, scaledPhase(problem), [0.1], [0.2, 0.3])).toThrow(
      /same length/i,
    );
  });
});

describe('decoding back to chemistry', () => {
  it('maps slot classes onto the clamped context', () => {
    const fixedCodes = [2, 3, 0, 0, 2, 2, 1, 2];
    const problem = buildXyProblem(model.flat, {
      lambda: 1,
      fixedCodes,
      freePositions: [0, 7],
    });
    const codes = codesFor(problem, [5, 4]);
    expect(codes[0]).toBe(5);
    expect(codes[7]).toBe(4);
    // Every clamped position must be untouched.
    for (const position of [1, 2, 3, 4, 5, 6]) {
      expect(codes[position]).toBe(fixedCodes[position]);
    }
  });
});
